function compareScreenshot(actual: Buffer, baselinePath: string): void {
  // Pixel baselines are generated by headless Chromium on macOS. Font
  // rasterisation differs enough on Linux runners to make a 0.5% threshold
  // meaningless, so keep functional/browser/a11y checks on CI and treat the
  // pixel baseline as a local macOS gate.
  if (process.platform !== 'darwin') return;
  if (process.env.UPDATE_VISUAL === '1') {
    fs.mkdirSync(path.dirname(baselinePath), { recursive: true });
    fs.writeFileSync(baselinePath, actual);
    return;
  }
  assert.ok(fs.existsSync(baselinePath), `missing visual baseline ${baselinePath}; run UPDATE_VISUAL=1`);
  const expected = PNG.sync.read(fs.readFileSync(baselinePath));
  const received = PNG.sync.read(actual);
  assert.equal(received.width, expected.width, 'visual screenshot width matches baseline');
  assert.equal(received.height, expected.height, 'visual screenshot height matches baseline');
  const diff = new PNG({ width: expected.width, height: expected.height });
  const changed = pixelmatch(expected.data, received.data, diff.data, expected.width, expected.height, {
    threshold: 0.12,
  });
  const ratio = changed / (expected.width * expected.height);
  assert.ok(ratio <= 0.005, `pixel diff ratio ${(ratio * 100).toFixed(3)}% exceeds 0.5% (${changed} pixels)`);
}
const png = Buffer.from(
  'iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAusB9Y9Zl9sAAAAASUVORK5CYII=',
  'base64',
);
const html = `<!doctype html><html lang="zh-CN"><head><title>Markdown Studio smoke</title></head><body><style>html,body,#root{height:100%;margin:0}</style><div id="root"></div>
<script>
  window.__chunks = {};
  window.__ModuleLoader__ = {
    load(value) {
      if (value.chunk) window.__chunks[value.chunk] = value;
      else window.__definition = value;
    }
  };
</script>
<script src="/react.js"></script>
<script src="/react-dom.js"></script>
<script src="/client.js"></script>
<script>
  const dict = {};
  const locale = {
    getSnapshot: () => ({ revision: 1, locales: [{ id: 'zh' }] }),
    getLocale: () => ({ active: 'zh' }),
    subscribe: () => () => {},
    register: (ns, id, messages) => { dict[id] = Object.assign({}, dict[id] || {}, messages); return () => {}; },
    bind: () => (key) => (dict.zh && dict.zh[key]) || key,
  };
  const registrations = [];
  const ctx = {
    get: (name) => name === 'locale' ? locale : undefined,
    effect: (fn) => fn(),
    slots: {
      inject: (key, callback) => callback(),
      register: (options, component) => { registrations.push({ options, component }); return () => {}; },
    },
  };
  const makeRequire = () => {
    const req = (name) => {
      if (name === 'react') return window.React;
      if (name === '@deepseek-ai/dsh-client-ui-primitives') return null;
      throw new Error('unexpected module: ' + name);
    };
    req.async = async (spec) => {
      const chunkName = spec.replace(/^\\.\\//, '');
      if (!window.__chunks[chunkName]) {
        await new Promise((resolve, reject) => {
          const s = document.createElement('script');
          s.src = '/' + chunkName;
          s.onload = resolve;
          s.onerror = reject;
          document.head.appendChild(s);
        });
      }
      return window.__chunks[chunkName].factory(makeRequire());
    };
    return req;
  };
  const plugin = window.__definition.factory(makeRequire());
  plugin.apply(ctx);
  const main = registrations.find((entry) => entry.options.name === 'main').component;
  ReactDOM.createRoot(document.getElementById('root')).render(React.createElement(main, {}));
</script></body></html>`;

const server = http.createServer((req, res) => {
  const url = req.url || '/';
  if (url === '/') {
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(html);
    return;
  }
  const files: Record<string, { path: string; type: string }> = {
    '/client.js': { path: path.join(root, bundleDir, 'client.js'), type: 'text/javascript; charset=utf-8' },
    '/client.studio.js': {
      path: path.join(root, bundleDir, 'client.studio.js'),
      type: 'text/javascript; charset=utf-8',
    },
    '/api/markdown-studio/mermaid.js': {
      path: path.join(root, bundleDir, 'mermaid.js'),
      type: 'text/javascript; charset=utf-8',
    },
    '/api/markdown-studio/math.js': {
      path: path.join(root, bundleDir, 'math.js'),
      type: 'text/javascript; charset=utf-8',
    },
    '/axe.js': { path: path.join(root, 'node_modules/axe-core/axe.min.js'), type: 'text/javascript; charset=utf-8' },
    '/react.js': {
      path: path.join(root, 'node_modules/react/umd/react.development.js'),
      type: 'text/javascript; charset=utf-8',
    },
    '/react-dom.js': {
      path: path.join(root, 'node_modules/react-dom/umd/react-dom.development.js'),
      type: 'text/javascript; charset=utf-8',
    },
  };
  const file = files[url];
  if (!file) {
    res.writeHead(404);
    res.end('not found');
    return;
  }
  res.writeHead(200, { 'content-type': file.type });
  res.end(fs.readFileSync(file.path));
});
