const savedVisualStyles = (await page.evaluate(() => {
  const selectors = [
    '.mdstudio-root',
    '.mdstudio-body',
    '.mdstudio-preview-pane',
    '.mdstudio-stage',
    '.mdstudio-device',
    '.mdstudio-device-screen',
  ];
  const saved = selectors.map((selector) => [
    selector,
    document.querySelector<HTMLElement>(selector)?.getAttribute('style') ?? null,
  ]);
  for (const selector of selectors) {
    const element = document.querySelector<HTMLElement>(selector);
    if (!element) continue;
    element.style.setProperty('height', 'auto', 'important');
    element.style.setProperty('max-height', 'none', 'important');
    element.style.setProperty('overflow', 'visible', 'important');
    if (selector === '.mdstudio-stage') element.style.setProperty('flex', 'none', 'important');
  }
  const screen = document.querySelector<HTMLElement>('.mdstudio-device-screen');
  if (screen) screen.scrollTop = 0;
  return saved;
})) as Array<[string, string | null]>;
