const drawerAxe = await page.evaluate(async () => {
  const axe = (
    window as unknown as {
      axe?: {
        run: (
          context: Document,
          options: unknown,
        ) => Promise<{ violations: Array<{ id: string; impact: string | null; nodes: unknown[] }> }>;
      };
    }
  ).axe;
  if (!axe) return null;
  const result = await axe.run(document, { runOnly: { type: 'tag', values: ['wcag2a', 'wcag2aa'] } });
  return result.violations.map((violation) => ({
    id: violation.id,
    impact: violation.impact,
    nodes: violation.nodes.map((node) => {
      const item = node as { target: string[]; html: string };
      return { target: item.target, html: item.html.slice(0, 180) };
    }),
  }));
});
